              ' The pishacha can also be forced out if the victim eats a bowl of rice that has been cooked in holy water. When the possession ends, the pishacha reappears in an unoccupied space within 5 feet of the body. The target is immune to possession by the same pishacha for 24 hours after succeeding on the initial saving throw or after the possession ends.',
